function BackToCharacterList() {
  ToggleContent("Character", "CharacterListView");
  const tabs = document.querySelectorAll(".character-tab");
  for (let i = 0; i < tabs.length; i++) {
    tabs[i].classList.toggle("is-active", tabs[i].getAttribute("data-target") === LastCharacterDirectoryView);
  }
  ShowCharacterDirectory(LastCharacterDirectoryView || "CharacterCardsPanel");
  ScrollToContentTop();
}
